CREATE TABLE roles(id SERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL,description TEXT DEFAULT '',protected BOOLEAN DEFAULT false);
CREATE TABLE permissions(id SERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE role_permissions(role_id INT REFERENCES roles ON DELETE CASCADE,permission_id INT REFERENCES permissions ON DELETE CASCADE,PRIMARY KEY(role_id,permission_id));
CREATE TABLE users(id SERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,phone TEXT DEFAULT '',password_hash TEXT NOT NULL,active BOOLEAN DEFAULT true,primary_admin BOOLEAN DEFAULT false,token_version INT DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE user_roles(user_id INT REFERENCES users ON DELETE CASCADE,role_id INT REFERENCES roles ON DELETE CASCADE,PRIMARY KEY(user_id,role_id));
CREATE TABLE addresses(id SERIAL PRIMARY KEY,user_id INT NOT NULL REFERENCES users ON DELETE CASCADE,label TEXT DEFAULT 'Home',first_name TEXT NOT NULL,last_name TEXT NOT NULL,phone TEXT NOT NULL,address TEXT NOT NULL,city TEXT NOT NULL,additional_address TEXT DEFAULT '',country TEXT DEFAULT 'Jordan');
CREATE TABLE media(id SERIAL PRIMARY KEY,filename TEXT NOT NULL,path TEXT NOT NULL UNIQUE,alt TEXT DEFAULT '',title TEXT DEFAULT '',mime_type TEXT NOT NULL,size INT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE categories(id SERIAL PRIMARY KEY,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,description TEXT DEFAULT '',image TEXT DEFAULT '',parent_id INT REFERENCES categories ON DELETE RESTRICT,display_order INT DEFAULT 0,active BOOLEAN DEFAULT true,seo_title TEXT DEFAULT '',meta_description TEXT DEFAULT '',canonical_url TEXT DEFAULT '',noindex BOOLEAN DEFAULT false,CHECK(parent_id IS DISTINCT FROM id));
CREATE TABLE products(id SERIAL PRIMARY KEY,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,sku TEXT UNIQUE NOT NULL,short_description TEXT DEFAULT '',description TEXT DEFAULT '',regular_price NUMERIC(12,3) NOT NULL CHECK(regular_price>=0),sale_price NUMERIC(12,3) CHECK(sale_price>=0 AND sale_price<=regular_price),cost_price NUMERIC(12,3) DEFAULT 0 CHECK(cost_price>=0),stock_quantity INT NOT NULL DEFAULT 0 CHECK(stock_quantity>=0),low_stock_threshold INT DEFAULT 5 CHECK(low_stock_threshold>=0),stock_status TEXT DEFAULT 'in_stock' CHECK(stock_status IN ('in_stock','out_of_stock')),category_id INT REFERENCES categories ON DELETE RESTRICT,subcategory_id INT REFERENCES categories ON DELETE RESTRICT,featured BOOLEAN DEFAULT false,popular BOOLEAN DEFAULT false,on_sale BOOLEAN DEFAULT false,active BOOLEAN DEFAULT true,main_image TEXT DEFAULT '',seo_title TEXT DEFAULT '',meta_description TEXT DEFAULT '',canonical_url TEXT DEFAULT '',noindex BOOLEAN DEFAULT false,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE product_images(id SERIAL PRIMARY KEY,product_id INT NOT NULL REFERENCES products ON DELETE CASCADE,path TEXT NOT NULL,alt TEXT DEFAULT '',display_order INT DEFAULT 0);
CREATE TABLE product_attributes(id SERIAL PRIMARY KEY,product_id INT NOT NULL REFERENCES products ON DELETE CASCADE,name TEXT NOT NULL,value TEXT NOT NULL);
CREATE TABLE product_relations(product_id INT REFERENCES products ON DELETE CASCADE,related_id INT REFERENCES products ON DELETE CASCADE,PRIMARY KEY(product_id,related_id),CHECK(product_id<>related_id));
CREATE TABLE inventory_transactions(id SERIAL PRIMARY KEY,product_id INT REFERENCES products ON DELETE SET NULL,product_name TEXT NOT NULL,user_id INT REFERENCES users ON DELETE SET NULL,delta INT NOT NULL,before_quantity INT NOT NULL,after_quantity INT NOT NULL,reason TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE carts(id SERIAL PRIMARY KEY,user_id INT UNIQUE REFERENCES users ON DELETE CASCADE);
CREATE TABLE cart_items(cart_id INT REFERENCES carts ON DELETE CASCADE,product_id INT REFERENCES products ON DELETE CASCADE,quantity INT NOT NULL CHECK(quantity BETWEEN 1 AND 999),PRIMARY KEY(cart_id,product_id));
CREATE TABLE wishlists(id SERIAL PRIMARY KEY,user_id INT UNIQUE REFERENCES users ON DELETE CASCADE);
CREATE TABLE wishlist_items(wishlist_id INT REFERENCES wishlists ON DELETE CASCADE,product_id INT REFERENCES products ON DELETE CASCADE,PRIMARY KEY(wishlist_id,product_id));
CREATE TABLE coupons(id SERIAL PRIMARY KEY,code TEXT UNIQUE NOT NULL,description TEXT DEFAULT '',discount_type TEXT NOT NULL CHECK(discount_type IN ('percentage','fixed')),discount_amount NUMERIC(12,3) NOT NULL CHECK(discount_amount>0),minimum_order NUMERIC(12,3) DEFAULT 0 CHECK(minimum_order>=0),maximum_discount NUMERIC(12,3) CHECK(maximum_discount>=0),start_date TIMESTAMPTZ,expiration_date TIMESTAMPTZ,usage_limit INT CHECK(usage_limit>0),usage_per_user INT DEFAULT 1 CHECK(usage_per_user>0),active BOOLEAN DEFAULT true,CHECK(discount_type<>'percentage' OR discount_amount<=100));
CREATE TABLE coupon_products(coupon_id INT REFERENCES coupons ON DELETE CASCADE,product_id INT REFERENCES products ON DELETE CASCADE,PRIMARY KEY(coupon_id,product_id));
CREATE TABLE coupon_categories(coupon_id INT REFERENCES coupons ON DELETE CASCADE,category_id INT REFERENCES categories ON DELETE CASCADE,PRIMARY KEY(coupon_id,category_id));
CREATE TABLE orders(id SERIAL PRIMARY KEY,order_number TEXT UNIQUE NOT NULL,user_id INT REFERENCES users ON DELETE SET NULL,customer JSONB NOT NULL,shipping_address JSONB NOT NULL,subtotal NUMERIC(12,3) NOT NULL,discount NUMERIC(12,3) DEFAULT 0,shipping NUMERIC(12,3) DEFAULT 0,tax NUMERIC(12,3) DEFAULT 0,total NUMERIC(12,3) NOT NULL,payment_method TEXT NOT NULL,payment_status TEXT DEFAULT 'unpaid' CHECK(payment_status IN ('unpaid','paid','refunded')),status TEXT DEFAULT 'pending' CHECK(status IN ('pending','processing','paid','shipped','completed','cancelled','refunded')),notes TEXT DEFAULT '',inventory_restored BOOLEAN DEFAULT false,idempotency_key UUID UNIQUE NOT NULL,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE order_items(id SERIAL PRIMARY KEY,order_id INT REFERENCES orders ON DELETE CASCADE,product_id INT REFERENCES products ON DELETE SET NULL,name TEXT NOT NULL,sku TEXT NOT NULL,image TEXT DEFAULT '',quantity INT NOT NULL CHECK(quantity>0),unit_price NUMERIC(12,3) NOT NULL);
CREATE TABLE coupon_usage(id SERIAL PRIMARY KEY,coupon_id INT REFERENCES coupons ON DELETE RESTRICT,user_id INT REFERENCES users ON DELETE SET NULL,email TEXT NOT NULL,order_id INT UNIQUE REFERENCES orders ON DELETE CASCADE);
CREATE TABLE reviews(id SERIAL PRIMARY KEY,product_id INT REFERENCES products ON DELETE CASCADE,user_id INT REFERENCES users ON DELETE CASCADE,rating INT CHECK(rating BETWEEN 1 AND 5),title TEXT NOT NULL,body TEXT NOT NULL,status TEXT DEFAULT 'pending' CHECK(status IN ('pending','approved','hidden')),created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(product_id,user_id));
CREATE TABLE pages(id SERIAL PRIMARY KEY,title TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,published BOOLEAN DEFAULT false,seo_title TEXT DEFAULT '',meta_description TEXT DEFAULT '',canonical_url TEXT DEFAULT '',noindex BOOLEAN DEFAULT false,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE page_sections(id SERIAL PRIMARY KEY,page_id INT NOT NULL REFERENCES pages ON DELETE CASCADE,section_type TEXT NOT NULL,title TEXT DEFAULT '',subtitle TEXT DEFAULT '',content TEXT DEFAULT '',configuration JSONB DEFAULT '{}',display_order INT DEFAULT 0,enabled BOOLEAN DEFAULT true,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE menus(id SERIAL PRIMARY KEY,name TEXT NOT NULL,location TEXT UNIQUE NOT NULL);
CREATE TABLE menu_items(id SERIAL PRIMARY KEY,menu_id INT NOT NULL REFERENCES menus ON DELETE CASCADE,parent_id INT REFERENCES menu_items ON DELETE CASCADE,label TEXT NOT NULL,url TEXT DEFAULT '',category_id INT REFERENCES categories ON DELETE CASCADE,page_id INT REFERENCES pages ON DELETE CASCADE,display_order INT DEFAULT 0,CHECK(parent_id IS DISTINCT FROM id));
CREATE TABLE testimonials(id SERIAL PRIMARY KEY,name TEXT NOT NULL,body TEXT NOT NULL,image TEXT DEFAULT '',rating INT DEFAULT 5 CHECK(rating BETWEEN 1 AND 5),display_order INT DEFAULT 0,active BOOLEAN DEFAULT true);
CREATE TABLE contact_messages(id SERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT DEFAULT '',message TEXT NOT NULL,is_read BOOLEAN DEFAULT false,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE site_settings(key TEXT PRIMARY KEY,value JSONB NOT NULL);
CREATE TABLE audit_logs(id BIGSERIAL PRIMARY KEY,user_id INT REFERENCES users ON DELETE SET NULL,action TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT,description TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX products_category_idx ON products(category_id,subcategory_id);
CREATE INDEX products_active_idx ON products(active,popular,featured);
CREATE INDEX products_search_idx ON products USING GIN(to_tsvector('english',name || ' ' || description || ' ' || sku));
CREATE INDEX orders_user_idx ON orders(user_id,created_at DESC);
CREATE INDEX inventory_product_idx ON inventory_transactions(product_id,created_at DESC);
CREATE INDEX sections_page_idx ON page_sections(page_id,display_order);
CREATE INDEX reviews_product_idx ON reviews(product_id,status);
CREATE INDEX coupon_usage_idx ON coupon_usage(coupon_id,email);
